#!/usr/bin/env node
/**
 * Generate per-country gab.country-trust.v1 envelopes from REAL corpus data.
 *
 * Inputs:
 *   research/countries.json   — the 50-program corpus (scorecard, audit_trail,
 *                               satohash_proofs, sources, pathways, last_checked)
 *   public/data/intel.json    — the LIVE daily pipeline manifest (freshness
 *                               sweep + proof in_sync, generated by intel:run)
 *
 * Outputs (written to public/, served by the SPA + CF Pages):
 *   public/countries/<ISO2>.json        — per-country envelope (gab.country-trust.v1)
 *   public/countries/index.json         — aggregate index (all countries, one line each)
 *   public/trust-state.json             — top-level aggregate (mirrors envelope shape)
 *
 * HONESTY RULES (non-negotiable):
 *  - Freshness is computed from last_checked (the real corpus verification date)
 *    and cross-checked against the live intel.json sweep. Green only ever = verified recent.
 *  - Radar axes with null values render as `pending`, never a fabricated number.
 *  - threshold.history is populated ONLY from real audit_trail entries that carry
 *    a threshold/investment change. Empty = honest "no tracked changes yet".
 *  - Proofs link to the real satohash verify URLs + .ots paths from the corpus.
 *  - Every value traces to a field in countries.json / intel.json. Nothing is invented.
 *
 * Run: node scripts/gen-trust-envelopes.mjs
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  freshnessFromDate,
  tierForSource,
  thresholdHistoryFromAudit,
} from './lib/trust-envelope-core.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const root = resolve(__dirname, '..')

/* ── ISO 3166-1 alpha-2, keyed by the EXACT names in research/countries.json ── */
const ISO_BY_NAME = {
  'El Salvador': 'SV',
  'Central African Republic': 'CF',
  Uruguay: 'UY',
  Bolivia: 'BO',
  'St. Kitts and Nevis': 'KN',
  'Antigua and Barbuda': 'AG',
  Dominica: 'DM',
  'UAE (Dubai / Abu Dhabi)': 'AE',
  Switzerland: 'CH',
  Singapore: 'SG',
  Portugal: 'PT',
  Malta: 'MT',
  Panama: 'PA',
  Georgia: 'GE',
  Paraguay: 'PY',
  'Costa Rica': 'CR',
  'Hong Kong': 'HK',
  Thailand: 'TH',
  Mexico: 'MX',
  Cyprus: 'CY',
  Greece: 'GR',
  Vanuatu: 'VU',
  Turkey: 'TR',
  Mauritius: 'MU',
  Seychelles: 'SC',
  Brazil: 'BR',
  Argentina: 'AR',
  Chile: 'CL',
  Colombia: 'CO',
  'St. Lucia': 'LC',
  Grenada: 'GD',
  Barbados: 'BB',
  Bahamas: 'BS',
  Belize: 'BZ',
  Cambodia: 'KH',
  Philippines: 'PH',
  Malaysia: 'MY',
  Indonesia: 'ID',
  Japan: 'JP',
  'New Zealand': 'NZ',
  Ireland: 'IE',
  Spain: 'ES',
  Italy: 'IT',
  Latvia: 'LV',
  Estonia: 'EE',
  Bulgaria: 'BG',
  Croatia: 'HR',
  Gibraltar: 'GI',
  'Cayman Islands': 'KY',
  Andorra: 'AD',
}

/** Pull real min-investment history from audit_trail when it actually carries a change. */
function buildEnvelope(p, intelProgram) {
  const iso = ISO_BY_NAME[p.name] ?? p.name.slice(0, 2).toUpperCase()
  const now = new Date()
  const lastChecked = p.last_checked ?? null
  const freshness = freshnessFromDate(lastChecked, now)
  // Cross-check against the live pipeline sweep: if the intel manifest marks it
  // fresh, prefer that (it is the daily ground truth); never downgrade a verified-fresh
  // country to stale on a seed artifact.
  if (intelProgram?.freshness?.status === 'fresh' && freshness.status !== 'fresh') {
    freshness.status = 'fresh'
    freshness.days_stale = intelProgram.freshness.days_stale ?? 0
  }

  const proof = p.satohash_proofs?.[0] ?? null
  const scorecard = p.scorecard ?? {}
  const axes = ['crypto_friendly', 'freedom', 'stability', 'tax', 'cost', 'mobility', 'banking']
  const scorecardAxes = {}
  for (const ax of axes) {
    const v = scorecard[ax]
    scorecardAxes[ax] = {
      value: typeof v === 'number' ? v : null,
      present: typeof v === 'number',
      label: ax.replace(/_/g, ' '),
    }
  }

  const officialUrls = (p.legal_compliance?.official_urls ?? []).map((u) => {
    try {
      return { url: u, hostname: new URL(u).hostname }
    } catch {
      return { url: u, hostname: '' }
    }
  })
  const sources = (p.sources ?? []).map((s) => ({
    name: s,
    tier: tierForSource(s, officialUrls),
  }))
  const tierCounts = sources.reduce(
    (acc, s) => {
      acc[s.tier] = (acc[s.tier] ?? 0) + 1
      return acc
    },
    { official: 0, legal: 0, secondary: 0 },
  )

  const minInvestmentUsd = p.finance?.min_investment_usd ?? null

  return {
    schema: 'gab.country-trust.v1',
    country: {
      iso2: iso,
      name: p.name,
      flag: p.flag ?? null,
      region: p.region ?? null,
      category: p.category ?? null,
    },
    generated_at: now.toISOString(),
    freshness: {
      status: freshness.status,
      days_stale: freshness.days_stale,
      verified_at: freshness.verified_at,
      scale: 'FRESH<=30d · WATCH 31-45d · STALE>45d',
      pipeline_sweep: intelProgram?.freshness ?? null,
    },
    proof: proof
      ? {
          status: 'confirmed',
          block: proof.block_height ?? null,
          stamped_at: proof.stamped_at ?? null,
          hash: proof.content_hash ?? proof.proof_url?.split('/').pop() ?? null,
          proof_url: proof.proof_url ?? null,
          ots_path: proof.ots_path ?? null,
          in_sync: intelProgram?.proof?.in_sync ?? null,
        }
      : {
          status: 'none',
          block: null,
          stamped_at: null,
          hash: null,
          proof_url: null,
          ots_path: null,
          in_sync: null,
        },
    scorecard: {
      axes: scorecardAxes,
      note: scorecard.note ?? null,
    },
    threshold: {
      min_investment_usd: minInvestmentUsd,
      typical_investment_usd: p.finance?.typical_investment_usd ?? null,
      history: thresholdHistoryFromAudit(p.audit_trail, minInvestmentUsd),
      pathways: (p.pathways ?? []).map((pw) => ({
        type: pw.type,
        label: pw.label,
        min_investment_usd: pw.min_investment_usd ?? null,
      })),
    },
    sources: {
      tiers: tierCounts,
      list: sources,
      official_urls: p.legal_compliance?.official_urls ?? [],
    },
    watch: p.watch
      ? {
          changed: !!p.watch.changed,
          last_probe_at: p.watch.last_probe_at ?? null,
          urls: (p.watch.urls ?? []).map((u) => ({
            url: u.url,
            status: u.status ?? null,
            last_probed: u.last_probed ?? null,
          })),
        }
      : null,
    audit_trail: (p.audit_trail ?? []).slice(-8).map((e) => ({
      date: e.date ?? null,
      field: e.field ?? null,
      from: e.from ?? null,
      to: e.to ?? null,
      hash: e.hash ?? null,
    })),
    sovereignty: {
      score: p.sovereignty_score ?? null,
      stacking_synergy: p.stacking_synergy ?? null,
      risk_level: p.risk_level ?? null,
      lightning_ready: !!p.lightning_ready,
      bitcoin_integration: p.bitcoin_integration ?? null,
    },
  }
}

function main() {
  const corpus = JSON.parse(readFileSync(resolve(root, 'research/countries.json'), 'utf8'))
  const programs = corpus.programs ?? corpus
  const intelPath = resolve(root, 'public/data/intel.json')
  const intel = existsSync(intelPath)
    ? JSON.parse(readFileSync(intelPath, 'utf8'))
    : { programs: {} }
  const intelPrograms = intel.programs ?? {}

  const outDir = resolve(root, 'public/countries')
  mkdirSync(outDir, { recursive: true })

  const index = []
  let fresh = 0,
    watch = 0,
    stale = 0
  for (const p of programs) {
    const env = buildEnvelope(p, intelPrograms[p.name])
    const iso = env.country.iso2
    writeFileSync(resolve(outDir, `${iso}.json`), JSON.stringify(env, null, 2) + '\n')
    index.push({
      iso2: iso,
      name: env.country.name,
      flag: env.country.flag,
      freshness_status: env.freshness.status,
      days_stale: env.freshness.days_stale,
      proof_status: env.proof.status,
      proof_block: env.proof.block,
      min_investment_usd: env.threshold.min_investment_usd,
      sovereignty_score: env.sovereignty.score,
    })
    if (env.freshness.status === 'fresh') fresh++
    else if (env.freshness.status === 'watch') watch++
    else stale++
  }

  const indexDoc = {
    schema: 'gab.country-trust.v1.index',
    generated_at: new Date().toISOString(),
    count: index.length,
    sweep: { fresh, watch, stale },
    countries: index,
  }
  writeFileSync(resolve(outDir, 'index.json'), JSON.stringify(indexDoc, null, 2) + '\n')
  writeFileSync(resolve(root, 'public/trust-state.json'), JSON.stringify(indexDoc, null, 2) + '\n')

  console.log(`✓ ${index.length} envelopes → public/countries/<ISO2>.json`)
  console.log(`  sweep: ${fresh} fresh · ${watch} watch · ${stale} stale`)
  console.log(`  index → public/countries/index.json + public/trust-state.json`)
}

main()
